inline int developerTest(const fs::path& folder){try{INITCOMMONCONTROLSEX init{sizeof init,ICC_LISTVIEW_CLASSES|ICC_STANDARD_CLASSES};InitCommonControlsEx(&init);auto store=std::make_shared<Store>(folder);store->load();App app(store);bool blocked=false;try{app.setPage(11);}catch(...){blocked=true;}if(!blocked)throw std::runtime_error("Non-developer management page accepted");auto parent=CreateWindowExW(0,L"STATIC",L"",0,0,0,700,500,nullptr,nullptr,GetModuleHandle(nullptr),nullptr);if(!parent)throw std::runtime_error("Hidden management parent failed");app.hwnd=parent;app.page=11;app.accountProfile={{"role","develop"}};app.developerRows=json::array({{{"id","test-account"},{"email","test@example.com"},{"role","safe"},{"owner","test-owner"},{"enabled",true}}});app.developerControls({0,0,600,400},{0,440,600,200});if(ListView_GetItemCount(app.positive)!=1||Header_GetItemCount(ListView_GetHeader(app.positive))!=5)throw std::runtime_error("Management table row/column mismatch");ListView_SetItemState(app.positive,0,LVIS_SELECTED,LVIS_SELECTED);if(str(app.developerSelection(),"id")!="test-account")throw std::runtime_error("Management selection mismatch");app.accountProfile={{"role","safe"}};blocked=false;try{app.developerRequest("list","GET","/api/develop/accounts");}catch(...){blocked=true;}if(!blocked)throw std::runtime_error("Non-developer request accepted");app.clearControls();DestroyWindow(parent);app.hwnd=nullptr;app.engine->stopping=true;app.engine->cv.notify_all();delete app.engine;app.engine=nullptr;atomicWrite(folder/"developer-result.json",json{{"ok",true},{"gui_opened",false},{"ordinary_user_blocked",blocked},{"table_columns",5}}.dump(2));return 0;}catch(const std::exception& e){atomicWrite(folder/"developer-result.json",json{{"ok",false},{"error",e.what()},{"gui_opened",false}}.dump(2));return 1;}}
